import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n cart lines of `price` each (qty 1).
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (issue #12)', () => {
  // 1000 * (1 - 0.1) = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('10 or more lines: customer discount, then the 5% bulk discount once (issue #12)', () => {
  // 10000 * (1 - 0.1) = 9000, then 9000 * (1 - 0.05) = 8550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('9 lines: customer discount only, no bulk discount (issue #12)', () => {
  // 9000 * (1 - 0.1) = 8100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('discount rate 0 leaves the total unchanged (issue #12)', () => {
  // fewer than 10 lines: no discount at all
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
  // 10 lines, subtotal 999: bulk only, 999 * 0.95 = 949.05 -> 949
  assert.equal(total([...lines(9, 100), { price: 99, qty: 1 }], 0), 949);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
